{"concepto": "Attention Score (Attention Logits)", "enunciado": "$QK^T / \\sqrt{d_k}$ (valor antes de softmax)", "problema": "Determinar la importancia relativa que un token de consulta debe asignar a cada token de clave", "limite": "Valores no normalizados; rango depende de dimensión d_k y magnitudes de Q, K", "patron": "Un scoring bilineal entre pares de vectores, escalado inversamente por raíz cuadrada de dimensión para estabilizar", "linea": 74}
{"concepto": "Local Head (Cabeza de Atención Local)", "enunciado": "Enfoque en tokens adyacentes con patrón diagonal en matriz de atención", "problema": "Capturar dependencias sintácticas y colocaciones de corto alcance", "limite": "Efectivo solo para distancias pequeñas; no accede a información distante", "patron": "Ventana deslizante que restringe visibilidad a rango fijo alrededor de cada posición", "linea": 95}
{"concepto": "Strided Head (Cabeza de Atención con Paso)", "enunciado": "Atención a tokens con pasos fijos y regulares en la secuencia", "problema": "Reconocer estructuras periódicas o regularidades que repiten cada n posiciones", "limite": "Solo detecta periodicidad exacta o cercana al paso elegido", "patron": "Indexación con incremento regular para muestreo sistemático de la secuencia", "linea": 96}
{"concepto": "Global Head (Cabeza de Atención Global)", "enunciado": "Distribución de atención casi uniforme sobre todos los tokens", "problema": "Agregar información global de contexto de toda la secuencia", "limite": "Costo cuadrático; puede diluir señal si hay ruido en la mayoría de posiciones", "patron": "Atención sin restricción posicional que mantiene acceso equitativo a toda entrada", "linea": 97}
{"concepto": "Position Head (Cabeza de Atención Posicional)", "enunciado": "Enfoque preferente en posiciones específicas como inicio de oración o párrafo", "problema": "Identificar y amplificar información en hitos estructurales del documento", "limite": "Requiere que la estructura sea predecible y consistente", "patron": "Amplificación selectiva de índices específicos (absolutos o relativos) en la secuencia", "linea": 98}
{"concepto": "Attention Sink (Fenómeno de Sumidero de Atención)", "enunciado": "Concentración de pesos de atención anormalmente altos en los primeros tokens de la secuencia, independientemente de relevancia semántica", "problema": "El softmax obliga a normalizar pesos a suma 1, forzando asignación aun cuando no hay señal significativa", "limite": "Específico a arquitecturas autoregresivas con softmax normalizador", "patron": "Un depósito por defecto donde la norma de probabilidad redirige masa hacia una posición de bajo costo (la primera)", "linea": 121}
{"concepto": "Gated Attention (Atención con Compuerta)", "enunciado": "$\\text{GatedAttention}(Q, K, V) = g \\odot \\text{softmax}\\left(\\frac{QK^T}{\\sqrt{d_k}}\\right) V$, donde $g$ es vector de compuerta aprendible", "problema": "Permitir que el modelo omita atención en posiciones innecesarias, reduciendo asignación forzada a Attention Sink", "limite": "Complejidad adicional en entrenamiento; requiere estabilidad numérica del gating", "patron": "Modulación elemento a elemento de salida mediante multiplicación por máscara aprendible para suprimir o amplificar canales selectivamente", "linea": 156}
